module multi_pipe_4bit #(
    parameter size = 4
) (
    input clk,
    input rst_n,
    input [size-1:0] mul_a,
    input [size-1:0] mul_b,
    output [2*size-1:0] mul_out
);

    reg [2*size-1:0] partial_products [size-1:0];
    reg [2*size-1:0] registers [size/2-1:0];
    reg [2*size-1:0] product;

    integer i;

    always @(*) begin
        for (i = 0; i < size; i = i + 1) begin
            if (mul_b[i]) begin
                partial_products[i] = mul_a << i;
            end else begin
                partial_products[i] = 'd0;
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (i = 0; i < size/2; i = i + 1) begin
                registers[i] <= 'd0;
            end
        end else begin
            for (i = 0; i < size/2; i = i + 1) begin
                registers[i] <= partial_products[2*i] + partial_products[2*i+1];
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            product <= 'd0;
        end else begin
            product <= registers[0];
            for (i = 1; i < size/2; i = i + 1) begin
                product <= product + registers[i];
            end
        end
    end

    assign mul_out = product;

endmodule
